    nv50->temp_celsius      = 42U;
    nv50->fan_percent       = 0U;
    nv50->vulkan_ready      = false;
    nv50->opengl_ready      = true;
    nv50->cuda_ready        = false;
    nv50->raytracing_ready  = false;
